"""Registrar leituras e inspeção visual do lote C-04 (registro 134)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==7
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,8)),same
notes={1:'Abertura do índice de termos, Por onde começar e Pessoas e relações em largura cheia.',2:'Fim de Pessoas e relações; Energia, efeitos e seres.',3:'Fim de Energia, efeitos e seres; Números que não significam a mesma coisa; exemplo e início dos exemplos de consulta.',4:'Fim dos exemplos de consulta em duas colunas; fecho do índice antes do apêndice com revelações.',5:'Abertura das ideias da obra em página própria, com o aviso de revelações; quadro de consultas; Ordens em conflito.',6:'Acesso disputado e Quem tem a resposta?; início de Aliados independentes.',7:'Aliados independentes, Histórias e desencontros e Quando o caso pede outra pesquisa.'}
save('revisao-final.json',{'registro':134,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das duas consultas, das regras citadas e das quatro sinopses oficiais disponíveis; duas cópias, remissões para os capítulos novos e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; nenhuma alteração necessária.'}],'ajuste_de_diagramacao':'Sem linhas de preencher (glossário e apêndice de consulta); quadros de termos em largura cheia; apêndice com revelações em página própria; rótulo CONSULTA no lugar de FICHA PARA A MESA.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if False else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Página 4 com um quarto de texto, fechando o índice antes do apêndice com revelações; a quebra é intencional.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s088':[1,4],'s087':[5,7]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':134,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':134,'lote':'C-04','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':59,'casos_pendentes':0,'lotes_pendentes':0,'consultas_revistas':17,'consultas_pendentes':0,'consultas_complementares_pendentes':0,'etapa_6':'em andamento','proximo_lote':'Conferência do conjunto','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':2},ensure_ascii=False))
